import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEl1,validEl1,advanceEl1,numericEl1,experimentOptions,experimentResult,experimentCases,experimentValid}from './el1-models.js?v=20261023-physicscomplete01';import{showEl1}from './el1-visuals.js?v=20261023-physicscomplete01';export{showEl1};
export function mountEl1(l,p,root,{save,done,feedback}){let ts=tasksForEl1(l.widget.slice(4)),w=p.widget;w.el1Task??=ts[0].id;w.el1Drafts??={};w.el1Passed??=[];let i=ts.findIndex(t=>t.id===w.el1Task);if(i<0)i=0;let t=ts[i],v=w.el1Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEl1(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.el1Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('el1Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('el1Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEl1">Reveal evidence →</button><p id="el1Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEl1(t.kind,{state:c[0],quiz:t.kind==='symbols',title:t.title,label:c[1],concealed:t.kind==='symbols'?false:!r,progress:r?1:0,step:r?5:0});$('#el1Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEl1(c,v.answer);}
else if(t.type==='sequence'){body=field('el1Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEl1">Advance pathway →</button><p id="el1Readout" aria-live="polite"></p>';draw=()=>{showEl1(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#el1Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('el1A',o.labels[0],o.a,v.a)+field('el1B',o.labels[1],o.b,v.b)+'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="el1Prediction" value="'+(v.prediction??'')+'"></label><button class="secondary" id="el1Run">Reveal model output →</button><p id="el1Output"></p>'+(t.experiment==='symbols'?field('el1Wiring','Meter arrangement',[['correct','Ammeter series; voltmeter parallel'],['wrong','Ammeter parallel; voltmeter series']],v.wiring):'')+field('el1Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showEl1(t.kind,{a:v.a,b:v.b,wiring:v.wiring,revealed:v.ran,title:t.title});$('#el1Output').textContent=t.experiment==='symbols'&&v.wiring!=='correct'?'Choose correct meter placement before interpreting the path count.':(v.ran?'Model output: '+Number(r.value.toFixed(3))+' '+o.unit:(t.experiment==='wire'?'Virtual readings: '+r.V+' V and'+r.I+' A at the selected length. Predict resistance.':'Predict first. Use the given equation or energy account.'));};valid=()=>!!v.ran&&(t.experiment!=='symbols'||v.wiring==='correct')&&numericEl1(v.prediction,experimentResult(t.experiment,v.a,v.b).value);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="el1Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="el1Number" type="number" step="any" value="'+(v.number??'')+'">'+field('el1Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEl1(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEl1(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="el1Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEl1">Record reasoning</button><button class="secondary" id="nextEl1">Next challenge →</button></div><p id="el1Progress"></p>';
const status=()=>{$('#el1Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.el1Passed.includes(t.id)?'Challenge recorded.':'';$('#el1Progress').textContent=ts.filter(t=>w.el1Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='el1A'||id==='el1B'){if(!val){remount();return;}v[id==='el1A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='el1Wiring'){v.wiring=val;save();draw();return;}if(id==='el1Interpretation'){v.interpretation=val;save();return;}if(id==='el1Prediction'){v.prediction=val;save();return;}if(id==='el1Case'){if(val===''){remount();return;}v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='el1Answer')v.answer=val;else if(id==='el1Next')v.next=val;else if(id==='el1Number')v.number=val;else if(id==='el1Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='el1Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#el1Run'))$('#el1Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Predict a number first.',true);return;}v.ran=true;save();draw();};
if($('#revealEl1'))$('#revealEl1').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEl1(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEl1(t.cases[v.case],v.answer));};
if($('#advanceEl1'))$('#advanceEl1').onclick=()=>{let n=advanceEl1(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEl1').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.el1Passed.includes(t.id))w.el1Passed.push(t.id);p.widgetDone=ts.every(t=>w.el1Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextEl1').onclick=()=>{if(!w.el1Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.el1Task=ts[(i+1)%ts.length].id;save();remount();};}
